from pathlib import Path
import base64

root=Path(__file__).resolve().parents[1]
base=root/'knowledge/operations/syndication'
def logo(name):
    encoded=base64.b64encode((root/'knowledge/1-brand/assets/logos'/name).read_bytes()).decode()
    return 'data:image/png;base64,'+encoded
light=logo('logo-for-dark-bg.png');dark=logo('logo-for-light-bg.png')
